package tui

import (
	"encoding/json"
	"os"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"
)

// The golden file is generated by driving the upstream TuiAltScreen with a fake
// recording terminal and scripted content/input steps, then dumping the
// concatenated writes per step and the text its copySelection hook received
// (tui/testdata/altscreen/generate.mjs).

type altScreenStep struct {
	Lines   []string `json:"lines"`
	Inputs  []string `json:"inputs"`
	Flashes []string `json:"flashes"`
	Columns *int     `json:"columns"`
	Rows    *int     `json:"rows"`
}

type altScreenSpec struct {
	Steps         []altScreenStep `json:"steps"`
	Indicator     bool            `json:"indicator"`
	CopySelection bool            `json:"copySelection"`
	Stop          bool            `json:"stop"`
	// Verbatim renders lines unchanged instead of padding them to the width,
	// for a line whose raw length carries an escape sequence or a wide glyph
	// past the width (padding by rune count would make the clamp drop the
	// reset, D470).
	Verbatim bool `json:"verbatim"`
}

type altScreenGolden struct {
	Spec   altScreenSpec `json:"spec"`
	Steps  []string      `json:"steps"`
	Copied [][]string    `json:"copied"`
	URLs   [][]string    `json:"urls"`
	Pastes [][]string    `json:"pastes"`
}

// TestAltScreenAgainstUpstreamGolden replays the upstream write streams and the
// text copy-on-select handed to the clipboard hook.
func TestAltScreenAgainstUpstreamGolden(t *testing.T) {
	data, err := os.ReadFile("testdata/altscreen/golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var golden map[string]altScreenGolden
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}

	labels := make([]string, 0, len(golden))
	for label := range golden {
		labels = append(labels, label)
	}
	sortStrings(labels)

	for _, label := range labels {
		want := golden[label]
		spec := want.Spec
		terminal := &recordingTerminal{width: 24, height: 6}
		options := AltScreenOptions{}
		if spec.Indicator {
			options.ScrollToEndIndicator = func() string { return " ↓ Jump to latest message " }
		}
		var copiedMu sync.Mutex
		var copied []string
		var openedMu sync.Mutex
		var opened []string
		var pasted []string
		options.OpenURL = func(url string) {
			openedMu.Lock()
			opened = append(opened, url)
			openedMu.Unlock()
		}
		options.OnRightClickPaste = func() {
			openedMu.Lock()
			pasted = append(pasted, "paste")
			openedMu.Unlock()
		}
		if spec.CopySelection {
			options.CopySelection = func(text string) (bool, bool, string) {
				copiedMu.Lock()
				copied = append(copied, text)
				copiedMu.Unlock()
				return true, true, ""
			}
		}
		screen := NewAltScreen(terminal, false, t.TempDir(), options)
		// Finish any pending copy and stop the renderer when the case ends.
		t.Cleanup(func() {
			screen.copyQueue.Flush()
			screen.Stop(TuiStopOptions{})
		})
		screen.DisableAutoRender()
		var setLines func([]string)
		if spec.Verbatim {
			verbatim := &fixedLinesComponent{}
			screen.AddChild(verbatim)
			setLines = func(lines []string) { verbatim.lines = lines }
		} else {
			component := &scriptedComponent{}
			screen.AddChild(component)
			setLines = func(lines []string) { component.lines = lines }
		}

		terminal.writes = nil
		inputHandler := func(data string) { screen.HandleTerminalInput(data) }
		screen.Start()

		// waitCopies blocks until the copies fired off-loop for the step at
		// index have all run, then returns them in order.
		waitCopies := func(index int) []string {
			t.Helper()
			if index >= len(want.Copied) {
				t.Fatalf("%s: golden has no copy slot for step %d", label, index)
			}
			expected := len(want.Copied[index])
			deadline := time.Now().Add(2 * time.Second)
			for {
				copiedMu.Lock()
				got := len(copied)
				copiedMu.Unlock()
				if got >= expected {
					break
				}
				if time.Now().After(deadline) {
					t.Fatalf("%s step %d: %d copies, want %d", label, index, got, expected)
				}
				time.Sleep(time.Millisecond)
			}
			copiedMu.Lock()
			defer copiedMu.Unlock()
			texts := append([]string(nil), copied...)
			copied = nil
			return texts
		}

		var steps []string
		steps = append(steps, strings.Join(terminal.writes, ""))
		if got := waitCopies(0); len(got) != 0 {
			t.Fatalf("%s: copies before any input: %v", label, got)
		}

		for index, step := range spec.Steps {
			if step.Lines != nil {
				setLines(step.Lines)
			}
			if step.Columns != nil {
				terminal.width = *step.Columns
			}
			if step.Rows != nil {
				terminal.height = *step.Rows
			}
			for _, input := range step.Inputs {
				inputHandler(input)
			}
			for _, flash := range step.Flashes {
				screen.Flash(flash)
			}
			// The copy runs off-loop; let it finish before the frame is drawn so
			// its flash lands in this step on both sides, as it does upstream.
			got, wantCopied := waitCopies(index+1), want.Copied[index+1]
			if !slices.Equal(got, wantCopied) {
				t.Fatalf("%s step %d copied:\n got %q\nwant %q", label, index+1, got, wantCopied)
			}
			openedMu.Lock()
			gotURLs, wantURLs := append([]string(nil), opened...), want.URLs[index+1]
			gotPastes, wantPastes := append([]string(nil), pasted...), want.Pastes[index+1]
			opened, pasted = nil, nil
			openedMu.Unlock()
			if !slices.Equal(gotURLs, wantURLs) {
				t.Fatalf("%s step %d opened URLs:\n got %q\nwant %q", label, index+1, gotURLs, wantURLs)
			}
			if !slices.Equal(gotPastes, wantPastes) {
				t.Fatalf("%s step %d pastes:\n got %q\nwant %q", label, index+1, gotPastes, wantPastes)
			}
			terminal.writes = nil
			screen.RenderNow(false)
			steps = append(steps, strings.Join(terminal.writes, ""))
		}
		if spec.Stop {
			terminal.writes = nil
			screen.Stop(TuiStopOptions{})
			steps = append(steps, strings.Join(terminal.writes, ""))
			got, wantCopied := waitCopies(len(steps)-1), want.Copied[len(steps)-1]
			if !slices.Equal(got, wantCopied) {
				t.Fatalf("%s stop copied:\n got %q\nwant %q", label, got, wantCopied)
			}
		}
		if len(steps) != len(want.Steps) {
			t.Fatalf("%s: %d steps, want %d", label, len(steps), len(want.Steps))
		}
		for index := range steps {
			if steps[index] != want.Steps[index] {
				t.Fatalf("%s step %d:\n got %q\nwant %q", label, index, steps[index], want.Steps[index])
			}
		}
	}
}

// TestAltScreenSelectionHelpers covers the selection text extraction and
// highlight application without a golden.
func TestAltScreenSelectionHelpers(t *testing.T) {
	terminal := &recordingTerminal{width: 20, height: 6}
	screen := NewAltScreen(terminal, false, t.TempDir(), AltScreenOptions{})
	screen.DisableAutoRender()
	component := &scriptedComponent{lines: []string{"hello world"}}
	screen.AddChild(component)
	screen.Start()
	screen.RenderNow(false)

	// Click and drag selects a range.
	pressed := func(data string) { screen.HandleTerminalInput(data) }
	pressed("\x1b[<0;1;1M")
	pressed("\x1b[<32;6;1M")
	pressed("\x1b[<0;6;1m")
	if !screen.HasActiveSelection() {
		t.Fatal("no active selection")
	}
	screen.SetCopyOnSelect(false)

	// A single click clears the selection.
	pressed("\x1b[<0;1;1M")
	pressed("\x1b[<0;1;1m")
	if screen.HasActiveSelection() {
		t.Fatal("selection not cleared")
	}
}

// TestAltScreenSearchOverlay covers the search toggle and query flow.
func TestAltScreenSearchOverlay(t *testing.T) {
	terminal := &recordingTerminal{width: 30, height: 8}
	screen := NewAltScreen(terminal, false, t.TempDir(), AltScreenOptions{})
	screen.DisableAutoRender()
	component := &scriptedComponent{lines: []string{"alpha beta", "gamma alpha"}}
	screen.AddChild(component)
	screen.Start()
	screen.RenderNow(false)

	screen.HandleTerminalInput("\x1b[102;6u") // ctrl+shift+f
	if screen.activeSearch == nil {
		t.Fatal("search not opened")
	}
	for _, character := range "alpha" {
		screen.HandleTerminalInput(string(character))
	}
	screen.RenderNow(false)
	if len(screen.activeSearch.Matches) != 2 {
		t.Fatalf("matches = %d", len(screen.activeSearch.Matches))
	}
	// Navigating to a match reveals it, which disables follow-end.
	screen.HandleTerminalInput("\r")
	screen.RenderNow(false)
	if selected := screen.activeSearch.SelectedIndex; selected < 0 {
		t.Fatalf("no selected match after navigate: %d", selected)
	}
	screen.HandleTerminalInput("\x1b")
	if screen.activeSearch != nil {
		t.Fatal("search not closed")
	}
}

// pi v1.5.0 tui-alt-screen.ts uses iTerm2's default word characters, so a
// double click keeps paths, kebab/snake tokens, dotted names and Windows paths
// together.
func TestTerminalWordSelectionJoinersMatchITerm2(t *testing.T) {
	for _, segment := range []string{"/", "-", "+", "\\", "~", "_", "."} {
		if !terminalWordSelectionJoiners[segment] {
			t.Errorf("%q must join a selected word", segment)
		}
	}
	for _, segment := range []string{" ", ":", ","} {
		if terminalWordSelectionJoiners[segment] {
			t.Errorf("%q must not join a selected word", segment)
		}
	}
}
